<!doctype html><html><head><meta charset="utf-8"><style>body{font:14px Arial,sans-serif;color:#222;margin:36px}h1{color:#333}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.muted{color:#666}.classic h1{border-bottom:3px double #555;padding-bottom:14px}.classic th{background:#f0f0f0}.modern h1{color:#287db4}.modern th{color:#287db4;border-bottom:2px solid #287db4}</style></head><body class="<?= esc($quote->template_code ?? 'modern', 'attr') ?>">
<h1><?= esc($config['company'] ?? 'Company') ?></h1><h2><?= lang('Sales.quote') ?> <?= esc($quote->quote_number) ?></h2><p><?= esc($quote->customer_name) ?> · <?= lang('Quotations.valid_until') ?>: <?= esc($quote->valid_until) ?></p><p class="muted"><?= nl2br(esc($config['address'] ?? '')) ?></p>
<table><thead><tr><th><?= lang('Quotations.description') ?></th><th><?= lang('Quotations.quantity') ?></th><th><?= lang('Quotations.unit_price') ?></th><th class="right"><?= lang('Quotations.total') ?></th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= esc($item->item_name ?: $item->description) ?></td><td><?= esc($item->quantity_purchased) ?></td><td><?= to_currency($item->item_unit_price) ?></td><td class="right"><?= to_currency($item->quantity_purchased * $item->item_unit_price * (1 - $item->discount_percent / 100)) ?></td></tr><?php endforeach; ?><?php foreach ($taxes as $tax): ?><tr><td colspan="3"><?= esc($tax->name ?: $tax->tax_group) ?> (<?= esc($tax->tax_rate) ?>%)</td><td class="num"><?= to_currency($tax->sale_tax_amount) ?></td></tr><?php endforeach; ?></tbody></table><h3 class="right"><?= lang('Sales.total') ?>: <?= to_currency($total) ?></h3>
<?php if ($options): ?><h3><?= lang('Quotations.optional_items') ?></h3><ul><?php foreach ($options as $option): ?><li><?= esc($option->description) ?>: <?= esc($option->quantity) ?> × <?= to_currency($option->unit_price) ?></li><?php endforeach; ?></ul><?php endif; ?><p><?= nl2br(esc($quote->comment ?? '')) ?></p></body></html>
